import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BY72S51x.js";const n="/aibutler/docs-versions/v1.1.9/img/en/settings-search.png",g=JSON.parse('{"title":"Web Search","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/search.md","filePath":"en/guide/search.md"}'),o={name:"en/guide/search.md"};function i(d,e,l,h,c,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="web-search" tabindex="-1">Web Search <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;Web Search&quot;">​</a></h1><p>Personas can search the web. For personas on the Butler engine, the search method is set in System Settings; personas on a Claude subscription use Claude&#39;s own search, unaffected by this page.</p><h2 id="default-the-model-s-built-in-search" tabindex="-1">Default: the model&#39;s built-in search <a class="header-anchor" href="#default-the-model-s-built-in-search" aria-label="Permalink to &quot;Default: the model&#39;s built-in search&quot;">​</a></h2><p>With nothing configured, a persona uses whatever search its model provider includes. Claude and OpenAI generally have one; some models or gateways don&#39;t, and then it can&#39;t search.</p><h2 id="add-your-own-search-engine" tabindex="-1">Add your own search engine <a class="header-anchor" href="#add-your-own-search-engine" aria-label="Permalink to &quot;Add your own search engine&quot;">​</a></h2><p>System Settings → <strong>Tools</strong> → <strong>Web search</strong>:</p><ol><li>Click <strong>+ Add</strong> and pick one from the list that opens: Brave, Tavily or SearXNG.</li><li>Fill in a key if one&#39;s needed; for SearXNG, fill in your own server address.</li><li>Click <strong>Test</strong> and look for &quot;Works&quot; and a first result.</li><li>If you&#39;ve added several, use the up/down arrows to set the order — the one on top is tried first, and it falls through to the next if one fails.</li><li>When you close the settings window it asks whether to save your changes — click <strong>Save</strong>.</li></ol><p><img src="'+n+'" alt="Web search settings"></p><table tabindex="0"><thead><tr><th>Engine</th><th>Needs a key</th><th>Direct from mainland China</th></tr></thead><tbody><tr><td>Brave</td><td>Yes (<a href="https://brave.com/search/api/" target="_blank" rel="noreferrer">apply</a>)</td><td>No, needs a proxy</td></tr><tr><td>Tavily</td><td>Yes (<a href="https://tavily.com" target="_blank" rel="noreferrer">apply</a>)</td><td>Yes</td></tr><tr><td>SearXNG</td><td>Your own server address</td><td>Depends on your server</td></tr></tbody></table><p>In mainland China, add Tavily — it connects directly.</p><div class="warning custom-block"><p class="custom-block-title">Once you add one, only added engines are used</p><p>As soon as you add an engine, the persona uses only these — not the model&#39;s built-in search anymore. To switch back to the model&#39;s own search temporarily, check <strong>Disable these engines</strong>; your configurations stay saved, and unchecking it restores them.</p></div><p>Reopen the persona for changes to take effect.</p>',12)])])}const f=t(o,[["render",i]]);export{g as __pageData,f as default};
